$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ContinuationResults";$dest="$root\M78ContinuationSource\Scripts\v5"
try{if(Test-Path $dest){throw 'Preserve previous v5 tool stage'};New-Item -ItemType Directory $dest -Force|Out-Null;$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-case-tools-v5.json").Content|ConvertFrom-Json;$z="$dest\tools.zip";Invoke-WebRequest -UseBasicParsing "$base/$($m.archive)" -OutFile $z;if((Get-FileHash $z).Hash.ToLower() -ne $m.archiveSHA256){throw 'Tool ZIP SHA mismatch'};Expand-Archive -LiteralPath $z -DestinationPath $dest;$rows=@();foreach($f in $m.files){$p=Join-Path $dest $f.path;if((Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw 'Tool SHA mismatch'};$tokens=$null;$errors=$null;[void][Management.Automation.Language.Parser]::ParseFile($p,[ref]$tokens,[ref]$errors);if($errors.Count){throw 'Parser error'};$rows+=@{path=$p;sha256=$f.sha256;parserErrors=@()}};$receipt="$out\m78-continuation-case-tools-v5.json";@{scope='Validation-tooling only: precreate successful empty linker log. No runtime/source change.';tools=$rows}|ConvertTo-Json -Depth 4|Set-Content $receipt -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-case-tools-v5-stage.json" -Method Post -InFile $receipt|Out-Null}catch{$p="$out\m78-continuation-case-tools-v5-error.txt";[string]$_.Exception.Message|Set-Content $p;Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-case-tools-v5-error.txt" -Method Post -InFile $p|Out-Null;exit 1}
